/// The commands that are no tool, and why (key, reason).
pub const LEFT: &[(&str, &str)] = &[
    ("tasks/Tasks.subscribe", "listener"),
];

/// The tools a switch lets through: none unless it is on.
pub fn tools(switch: &dyn Switch) -> &'static [ToolSpec] {
    capnp_compiler::mcpgen::rt::visible(switch, TOOLS)
}

/// The function of the command a tool stands for (`<name>_cli::dispatch`).
pub fn runner(tool: &ToolSpec) -> Option<crate::tasks_cli::Runner> {
    crate::tasks_cli::dispatch(tool.words)
}
